.question{background:#fff;border-left:8px solid var(--gold);padding:1.1rem 1.3rem;border-radius:12px;box-shadow:0 4px 18px #073b4c14;margin:1.2rem 0}.question strong{color:#9a5a00}
.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:1rem;margin:1.25rem 0}.card{background:#fff;border:1px solid #d8ecec;border-radius:16px;padding:1.15rem;box-shadow:0 5px 16px #073b4c12}.card h3{margin-top:0;color:#087b8a}.tag{display:inline-block;background:var(--turq2);color:#075766;border-radius:999px;padding:.25rem .7rem;font-size:.85rem;font-weight:700;margin:.15rem}
details{background:#fff;border:1px solid var(--line);border-radius:14px;margin:.8rem 0;overflow:hidden;box-shadow:0 3px 12px #073b4c0d}summary{cursor:pointer;background:linear-gradient(90deg,#e8f8f7,#fff);padding:1rem 1.2rem;font-weight:800;color:#075766;list-style:none}summary::-webkit-details-marker{display:none}summary:before{content:'+';display:inline-grid;place-items:center;width:1.55rem;height:1.55rem;border-radius:50%;background:var(--turq);color:white;margin-right:.7rem}details[open] summary:before{content:'–'}.inside{padding:1rem 1.3rem 1.25rem}.inside h4{color:#087b8a;margin-bottom:.25rem}
.timeline{border-left:5px solid var(--turq);margin:1rem 0 1rem 1rem;padding-left:1.3rem}.event{position:relative;margin:0 0 1.25rem}.event:before{content:'';position:absolute;left:-1.72rem;top:.35rem;width:.8rem;height:.8rem;border-radius:50%;background:var(--gold);border:3px solid white;box-shadow:0 0 0 2px var(--turq)}.date{font-weight:900;color:#b34d35}
.source{background:var(--cream);border:1px solid #f1dfbd;border-radius:14px;padding:1.2rem;margin:1rem 0}.source blockquote{font-family:Georgia,serif;font-size:1.08rem;margin:.7rem 0;padding-left:1rem;border-left:4px solid var(--gold)}
.task{background:#073b4c;color:white;border-radius:16px;padding:1.25rem;margin:1rem 0}.task h3{color:#7ff1ec;margin-top:0}.task a{color:#fff}.task .tag{background:#fff;color:#073b4c}
.check{background:#f1fbfa;border:1px solid #bce8e6;border-radius:12px;padding:1rem}.answer{background:#fff5d7;border-left:5px solid var(--gold);padding:.8rem 1rem;border-radius:8px;margin-top:.7rem}
.stage{border-top:8px solid var(--turq);position:relative}.stage.red{border-color:var(--coral)}.stage.gold{border-color:var(--gold)}
.compare{width:100%;border-collapse:separate;border-spacing:0;margin:1rem 0;overflow:hidden;border-radius:12px;border:1px solid #cfe5e5}.compare th{background:#087b8a;color:#fff}.compare td,.compare th{padding:.75rem;border-bottom:1px solid #dcecec;text-align:left;vertical-align:top}.compare tr:last-child td{border-bottom:0}
.annex{width:100%;height:auto;border-radius:14px;border:1px solid #b7dada;box-shadow:0 6px 20px #073b4c20}.small{font-size:.9rem;color:var(--muted)}
@media(max-width:650px){.hero{padding:1.4rem}.hero:after{font-size:5rem}.compare{font-size:.88rem}}
